exercises.solution:
const students = [
  { name: "Ava", advisor: "Dr. Lee" },
  { name: "Ben", advisor: "Dr. Lee" },
];
function adviseesOf(name) {
  return students.filter(s => s.advisor === name).map(s => s.name);
}
console.log(adviseesOf("Dr. Lee"));

